use vstd::prelude::*;

verus! {

fn empty(n: u8) -> (result: Vec<f64>)
    ensures
        result.len() == n as usize,
{
    let mut v: Vec<f64> = Vec::new();
    let mut i: usize = 0;

    while i < n as usize
        invariant
            i <= n as usize,
            v.len() == i,
    {
        v.push(0.0);
        i += 1;
    }

    v
}

} // verus!